use std::io::{self, BufRead};

fn eval(line: &str) -> String {
    let mut st: Vec<i64> = Vec::new();
    for t in line.split_whitespace() {
        let d = t.strip_prefix('-').unwrap_or(t);
        if !d.is_empty() && d.bytes().all(|b| b.is_ascii_digit()) {
            match t.parse::<i64>() {
                Ok(v) => st.push(v),
                Err(_) => return "error: token".to_string(),
            }
        } else if t == "+" || t == "-" || t == "*" || t == "/" {
            if st.len() < 2 {
                return "error: underflow".to_string();
            }
            let b = st.pop().unwrap();
            let a = st.pop().unwrap();
            let r = match t {
                "+" => a.wrapping_add(b),
                "-" => a.wrapping_sub(b),
                "*" => a.wrapping_mul(b),
                _ => {
                    if b == 0 {
                        return "error: divzero".to_string();
                    }
                    a.wrapping_div(b)
                }
            };
            st.push(r);
        } else {
            return "error: token".to_string();
        }
    }
    if st.len() == 1 {
        st[0].to_string()
    } else {
        "error: leftover".to_string()
    }
}

fn main() {
    for line in io::stdin().lock().lines() {
        let line = line.unwrap();
        if line.trim().is_empty() {
            continue;
        }
        println!("{}", eval(&line));
    }
}

